package br.com.bancohorizonte.service; import br.com.bancohorizonte.entity.ContaBancaria; import br.com.bancohorizonte.exception.*; import java.math.BigDecimal;
public class MovimentacaoService { public void depositar(ContaBancaria conta,BigDecimal valor){validar(conta,valor);conta.creditar(valor);} public void sacar(ContaBancaria conta,BigDecimal valor){validar(conta,valor);if(conta.getSaldo().compareTo(valor)<0)throw new SaldoInsuficienteException();conta.debitar(valor);} private void validar(ContaBancaria conta,BigDecimal valor){if(valor==null||valor.compareTo(BigDecimal.ZERO)<=0)throw new ValorMovimentacaoInvalidoException();if(!conta.isAtiva())throw new ContaInativaException();} }
